import rulesJson from '../data/rules.json'
import domainsJson from '../data/domains.json'
import { GROUPS, summarize, type Coverage, type Domain, type Rule, type RuleGroup } from './rules'

// Server-only: import this from server functions and server routes, never from
// components. The JSON is generated by `cargo xtask docgen` and typed here, so a
// renamed field fails the type check; groups are checked at load.
const catalog: (Omit<Rule, 'group'> & { group: string })[] = rulesJson
const isGroup = (id: string): id is RuleGroup => GROUPS.some((g) => g.id === id)
export const rules: Rule[] = catalog
  .map((r) => {
    if (!isGroup(r.group)) throw new Error(`rules.json: unknown group ${r.group} on ${r.name}`)
    return { ...r, group: r.group }
  })
  .sort((a, b) => a.name.localeCompare(b.name))
export const domains: Domain[] = domainsJson
export const summaries = rules.map(summarize)

const byName = new Map(rules.map((r) => [r.name, r]))

export function getRule(name: string): Rule | undefined {
  return byName.get(name)
}

export function resolveRule(name: string): Rule | undefined {
  const normalized = name.replace(/_/g, '-')
  return getRule(name) ?? getRule(normalized) ?? rules.find((rule) =>
    rule.source.upstreamId === name || rule.source.upstreamId?.replace(/_/g, '-') === normalized,
  )
}

export function coverage(): Coverage {
  const sources: Record<string, number> = {}
  for (const r of rules) sources[r.source.label] = (sources[r.source.label] ?? 0) + 1
  return {
    total: rules.length,
    recommended: rules.filter((r) => r.recommended).length,
    crossFile: rules.filter((r) => r.crossFile).length,
    mappedToOfficial: rules.filter((r) => r.source.kind === 'Lints').length,
    groups: GROUPS.map((g) => ({
      ...g,
      count: rules.filter((r) => r.group === g.id).length,
      recommended: rules.filter((r) => r.group === g.id && r.recommended).length,
    })),
    domains: domains.map((d) => ({ name: d.name, count: d.rules.length })),
    sources: Object.entries(sources)
      .map(([label, count]) => ({ label, count }))
      .sort((a, b) => b.count - a.count),
  }
}
